=[[rlt_text13]],["jobend"]=[[fb27rw05]]},["rlt_text14"]={["arg1"]=[[文本输出]],["arg2"]=[[你畅游在太乙池中，清凉的池水让你全身舒畅，你运行内功，丹田处传来一股暖流，外冷内暖，这种感觉让你异常舒适。]],["id"]=[[rlt_text14]]},["rlt_text1400"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL望尘:我差了些没药与马钱子，你帮我弄点。]],["id"]=[[rlt_text1400]]},["rlt_text1401"]={["arg1"]=[[文本输出]],["arg2"]=[[你将没药交给望尘。]],["id"]=[[rlt_text1401]]},["rlt_text1402"]={["arg1"]=[[文本输出]],["arg2"]=[[你将马钱子交给望尘。]],["id"]=[[rlt_text1402]]},["rlt_text1403"]={["arg1"]=[[文本输出]],["arg2"]=[[望尘：你现在好些了吗？
